func TestListProviders_Connected(t *testing.T) {
	// Spin up a fake /v1/models server.
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/v1/models" || r.URL.Path == "/models" {
