	}
	cat := loadSnapshotTestCatalog(t)

	snapshot, err := assembleModelSnapshotFromServiceConfigWithOptions(context.Background(), sc, cat, cache.Root, modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshForce})
