 665	func (s *service) buildRoutingInputsWithCatalog(ctx context.Context, cat *modelcatalog.Catalog) (routing.Inputs, modelsnapshot.ModelSnapshot) {
 666		statuses := s.registry.Discover()
 667		statusByName := make(map[string]harnesses.HarnessStatus, len(statuses))
 668		for _, st := range statuses {
 669			statusByName[st.Name] = st
 670		}
 671		now := time.Now().UTC()
 672		var snapshot modelsnapshot.ModelSnapshot
 673		if s.opts.ServiceConfig != nil {
 674			if cacheRoot, err := serviceSnapshotCacheRoot(); err == nil {
 675				snapshot, _ = assembleModelSnapshotFromServiceConfigWithOptions(
 676					ctx,
 677					s.opts.ServiceConfig,
 678					cat,
 679					cacheRoot,
 680					modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshBackground},
 681				)
 682			}
 683		}
 684	
 685		var entries []routing.HarnessEntry
 686		for _, name := range s.registry.Names() {
 687			cfg, ok := s.registry.Get(name)
 688			if !ok {
 689				continue
 690			}
 691			st := statusByName[name]
 692			entry := routingHarnessEntryFromMetadata(name, cfg, st)
 693			if name == "fiz" && s.opts.ServiceConfig == nil {
 694				entry.AutoRoutingEligible = false
 695			}
 696	
 697			if qs, ok := subscriptionQuotaForHarness(name, time.Now()); ok {
 698				entry.QuotaOK = qs.OK
 699				entry.QuotaStale = qs.Present && !qs.Fresh
 700				entry.SubscriptionOK = qs.OK
 701				entry.QuotaPercentUsed = qs.PercentUsed
 702				entry.QuotaTrend = qs.Trend
 703				entry.QuotaReason = qs.Reason
 704			}
 705	
 706			// Native "fiz" harness: enumerate snapshot-derived provider rows.
 707			if name == "fiz" && s.opts.ServiceConfig != nil {
 708				entry.Providers = s.snapshotProviderEntries(ctx, cat, snapshot)
 709				// Tool support for the agent harness is per-(provider, model);
 710				// the harness-level baseline is whether ANY provider supports
 711				// tools. Engine OR-combines harness and provider SupportsTools
 712				// so this lets a per-model no_tools catalog flag actually fire
 713				// the RequiresTools gate when every provider's resolved model
 714				// is no-tools.
 715				if len(entry.Providers) > 0 {
 716					entry.SupportsTools = anyProviderSupportsTools(entry.Providers)
 717				} else {
 718					entry.Available = false
 719				}
 720			}
 721			s.applySubscriptionRoutingCost(&entry, cat)
 722			entries = append(entries, entry)
 723		}
 724		successRate, latencyMS := s.routeMetricSignals(now, s.routeAttemptTTL())
 725		return routing.Inputs{
 726			Harnesses:                    entries,
 727			ProviderSuccessRate:          successRate,
 728			ObservedLatencyMS:            latencyMS,
 729			ProviderQuotaExhaustedUntil:  s.providerQuotaExhaustedUntil(now),
 730			ModelEligibility:             serviceRoutingModelEligibility(entries, cat),
 731			ReasoningResolver:            serviceRoutingReasoningResolver(cat),
 732			EndpointLoadResolver:         s.routeEndpointLoadsResolver(now),
 733			StickyServerInstanceResolver: s.routeStickyServerInstanceResolver(now),
 734		}, snapshot
 735	}
