690				ServerInstance:  strings.TrimSpace(row.ServerInstance),
691			}
692			grouped[key] = append(grouped[key], row)
693		}
694		if len(grouped) == 0 {
695			return nil
696		}
697	
698		groupCountByProvider := make(map[string]int)
699		for key := range grouped {
700			groupCountByProvider[key.Provider]++
701		}
702	
703		keys := make([]snapshotProviderGroupKey, 0, len(grouped))
704		for key := range grouped {
705			keys = append(keys, key)
706		}
707		sort.Slice(keys, func(i, j int) bool {
708			if keys[i].Provider != keys[j].Provider {
709				return keys[i].Provider < keys[j].Provider
710			}
711			if keys[i].EndpointName != keys[j].EndpointName {
712				return keys[i].EndpointName < keys[j].EndpointName
713			}
714			if keys[i].EndpointBaseURL != keys[j].EndpointBaseURL {
715				return keys[i].EndpointBaseURL < keys[j].EndpointBaseURL
716			}
717			return keys[i].ServerInstance < keys[j].ServerInstance
718		})
719	
720		var entries []routing.ProviderEntry
721		for _, key := range keys {
722			pcfg, ok := s.opts.ServiceConfig.Provider(key.Provider)
723			if !ok || pcfg.ConfigError != "" {
724				continue
725			}
726			rows := append([]modelsnapshot.KnownModel(nil), grouped[key]...)
727			sort.Slice(rows, func(i, j int) bool {
728				if rows[i].EndpointName != rows[j].EndpointName {
729					return rows[i].EndpointName < rows[j].EndpointName
730				}
731				if rows[i].EndpointBaseURL != rows[j].EndpointBaseURL {
732					return rows[i].EndpointBaseURL < rows[j].EndpointBaseURL
733				}
734				if rows[i].ServerInstance != rows[j].ServerInstance {
735					return rows[i].ServerInstance < rows[j].ServerInstance
736				}
737				return rows[i].ID < rows[j].ID
738			})
739			discoveredIDs := snapshotModelIDs(rows)
740			if defaultModel := strings.TrimSpace(pcfg.Model); defaultModel != "" {
741				discoveredIDs = appendUniqueModelIDs(discoveredIDs, defaultModel)
742			}
743			ctxWindows, ctxSources := snapshotProviderContextWindows(ctx, pcfg, cat, rows, discoveredIDs)
744			endpointName := snapshotEndpointName(pcfg, key)
745			routeName := key.Provider
746			if groupCountByProvider[key.Provider] > 1 {
747				switch {
748				case endpointName != "":
749					routeName = endpointProviderRef(key.Provider, endpointName)
750				case key.ServerInstance != "":
751					routeName = endpointProviderRef(key.Provider, key.ServerInstance)
752				case key.EndpointBaseURL != "":
753					routeName = endpointProviderRef(key.Provider, key.EndpointBaseURL)
754				}
755			}
756			baseURL := key.EndpointBaseURL
757			if baseURL == "" {
758				baseURL = pcfg.BaseURL
759			}
760			serverInstance := key.ServerInstance
761			if serverInstance == "" {
762				serverInstance = pcfg.ServerInstance
763			}
764			serverInstance = serverinstance.Normalize(baseURL, serverInstance)
765			entry := routing.ProviderEntry{
766				Name:                      routeName,
767				BaseURL:                   baseURL,
768				ServerInstance:            serverInstance,
769				EndpointName:              endpointName,
770				EndpointBaseURL:           baseURL,
771				DefaultModel:              pcfg.Model,
772				Billing:                   pcfg.Billing,
773				CostClass:                 providerRoutingCostClass(pcfg.Type),
774				DiscoveredIDs:             discoveredIDs,
775				DiscoveryAttempted:        true,
